rules.formula:
Set(varScanAccepted, false);
Set(varFlowCallStarted, false);
Set(varLoadingExecutionStarted, false);
Set(varOcrEmpty, false);
Set(varAcceptedText, "");
Set(varErrorMessage, "");
Set(varResultJson, "");
Reset(TextRecognizer1)

If(
    App.ActiveScreen = scrScan && !varScanAccepted && !varFlowCallStarted,
    IfError(
        With(
            {
                candidates: SortByColumns(
                    AddColumns(
                        Filter(
                            TextRecognizer1.Results,
                            !IsBlank(TrimEnds(Text)) &&
                            !IsBlank(BoundingBox.Top) && BoundingBox.Top >= 0
                        ),
                        OcrTop, BoundingBox.Top,
                        OcrLeft, Coalesce(BoundingBox.Left, 0),
                        OcrPage, Coalesce(PageNumber, 1)
                    ),
                    "OcrTop", SortOrder.Ascending,
                    "OcrPage", SortOrder.Ascending,
                    "OcrLeft", SortOrder.Ascending,
                    "Text", SortOrder.Ascending
                )
            },
            If(
                IsEmpty(candidates),
                Set(varAcceptedText, "");
                Set(varOcrEmpty, true);
                Notify("Okunabilir bir ürün adı bulunamadı. Etiketi netleştirip yeniden tarayın.", NotificationType.Warning),
                Set(varAcceptedText, TrimEnds(First(candidates).Text));
                Set(varOcrEmpty, false);
                Set(varScanAccepted, true);
                Navigate(scrLoading, ScreenTransition.Fade)
            )
        ),
        Set(varAcceptedText, "");
        Set(varOcrEmpty, true);
        Notify("Görüntüdeki metin okunamadı. Lütfen yeniden tarayın.", NotificationType.Warning)
    )
)

If(
    varScanAccepted && !IsBlank(varAcceptedText) && !varFlowCallStarted && !varLoadingExecutionStarted,
    Set(varLoadingExecutionStarted, true);
    Set(varFlowCallStarted, true);
    IfError(
        Set(varFlowResponse, barcode_flow.Run(varAcceptedText));
        Set(varResultJson, varFlowResponse.result_json);
        IfError(
            ClearCollect(
                colParsedRows,
                ForAll(
                    Table(ParseJSON(varResultJson)) As row,
                    {
                        ItemNumber: Text(row.Value.ItemNumber),
                        ProductName: Text(row.Value.ProductName),
                        InventoryWarehouseId: Text(row.Value.InventoryWarehouseId),
                        AvailableOnHandQuantity: Coalesce(
                            IfError(
                                Value(row.Value.AvailableOnHandQuantity),
                                Blank()
                            ),
                            0
                        ),
                        ReservedOnHandQuantity: Coalesce(
                            IfError(
                                Value(row.Value.ReservedOnHandQuantity),
                                Blank()
                            ),
                            0
                        )
                    }
                )
            );
            ClearCollect(
                colProductGroups,
                AddColumns(
                    GroupBy(
                        colParsedRows,
                        ItemNumber,
                        WarehouseRows
                    ) As ProductGroup,
                    ProductName,
                    First(ProductGroup.WarehouseRows).ProductName,
                    HasNameConflict,
                    CountRows(
                        Distinct(
                            ProductGroup.WarehouseRows,
                            ProductName
                        )
                    ) > 1
                )
            );
            Navigate(scrResults, ScreenTransition.Fade),
            Set(varErrorMessage, "Stok verisi işlenirken bir hata oluştu.");
            Navigate(scrError, ScreenTransition.Fade)
        ),
        Set(varErrorMessage, "Stok bilgileri alınırken bir bağlantı hatası oluştu.");
        Navigate(scrError, ScreenTransition.Fade)
    )
)

Set(varAcceptedText, "");
Set(varErrorMessage, "");
Set(varScanAccepted, false);
Set(varFlowCallStarted, false);
Set(varLoadingExecutionStarted, false);
Set(varOcrEmpty, false);
Set(varResultJson, "");
ClearCollect(
    colProductGroups,
    {
        ItemNumber: "",
        ProductName: "",
        HasNameConflict: false,
        WarehouseRows: Table(
            {
                InventoryWarehouseId: "",
                AvailableOnHandQuantity: 0,
                ReservedOnHandQuantity: 0
            }
        )
    }
);
Clear(colProductGroups);
Set(varExpandedItemNumber, Blank())
